  function esc(value){return typeof escapeHtml==='function'?escapeHtml(String(value==null?'':value)):String(value==null?'':value)}
  function clone(value){return JSON.parse(JSON.stringify(value))}
  function dateKey(value){return typeof value==='string'?value:localDateKey(value||new Date())}
  function dateAtNoon(key){return new Date(key+'T12:00:00')}
  function addDays(key,amount){var d=dateAtNoon(key);d.setDate(d.getDate()+amount);return localDateKey(d)}
  function mondayOf(key){return addDays(key,-((dateAtNoon(key).getDay()+6)%7))}
  function monthKey(key){return String(key).slice(0,7)}
  function newId(prefix){return prefix+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8)}
  function money(value){return typeof fmtMoney==='function'?fmtMoney(value):'£'+Number(value||0).toLocaleString('en-GB')}
  function commit(snapshot,domains,action){
    if(typeof saveStateOrRollback==='function'&&!saveStateOrRollback(snapshot))return false;
    if(typeof emitLifeHubChange==='function')emitLifeHubChange({action:action,domains:domains,source:'v75',rendered:true});
    return true;
  }
  function error(id,message){var el=document.getElementById(id);if(el){el.textContent=message||'';el.hidden=!message;if(message)el.focus()}}

  function legacyPence(value){if(typeof value!=='number'||!Number.isFinite(value)||value<0)return null;var pence=Math.round(value*100);return Math.abs(value-pence/100)<1e-9&&pence<=99999999?pence:null}
  function parseCurrencyPence(value){
    if(typeof value==='number'){if(!Number.isFinite(value))return null;value=String(value)}
    if(typeof value!=='string')return null;
    var clean=value.trim();if(!/^(?:0|[1-9]\d{0,5})(?:\.\d{1,2})?$/.test(clean))return null;
    var parts=clean.split('.'),pence=Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'));
    return Number.isSafeInteger(pence)&&pence>=1&&pence<=99999999?pence:null;
  }
  function migrateMoneyRecord(row,fields){var changed=false;if(!row||typeof row!=='object'||Array.isArray(row))return false;fields.forEach(function(pair){if(row[pair[1]]!==undefined||row[pair[0]]===undefined)return;var pence=legacyPence(Number(row[pair[0]]));if(pence!==null){row[pair[1]]=pence;changed=true}});return changed}
  function migrateLifeHubV76(target){
    var state=target||STATE,before=clone(state),changed=false;
    if(state.debtCharges===undefined){state.debtCharges=[];changed=true}
    if(state.savingsWithdrawals===undefined){state.savingsWithdrawals=[];changed=true}
    (state.debts||[]).forEach(function(row){if(row.balance===undefined){row.balance=0;changed=true}if(migrateMoneyRecord(row,[['balance','balancePence'],['startingBalance','startingBalancePence'],['monthlyTarget','monthlyTargetPence']]))changed=true;if(row.startingBalancePence===undefined&&Number.isInteger(row.balancePence)){row.startingBalancePence=row.balancePence;row.startingBalance=row.balance;changed=true}});
    (state.savingsGoals||[]).forEach(function(row){if(row.current===undefined){row.current=0;changed=true}if(migrateMoneyRecord(row,[['target','targetPence'],['current','currentPence'],['monthlyContribution','monthlyContributionPence']]))changed=true});
    [[state.debtPayments,'payment'],[state.debtCharges,'charge'],[state.savingsDeposits,'deposit'],[state.savingsWithdrawals,'withdrawal']].forEach(function(group){(Array.isArray(group[0])?group[0]:[]).forEach(function(row){if(migrateMoneyRecord(row,[['amount','amountPence']]))changed=true;if(row.version===undefined){row.version=2;changed=true}if(row.type===undefined){row.type=group[1];changed=true}if(row.note===undefined){row.note='';changed=true}})});
    if(state.__lifeHubV76!==true){state.__lifeHubV76=true;changed=true}
    return {changed:changed,before:before};
  }

  function normalizeReminder(stored,defaults){
    var next=Object.assign({},defaults,stored||{});next.schedule=Object.assign({},defaults.schedule,(stored&&stored.schedule)||{});
    if(typeof next.hour==='number'&&typeof next.minute==='number'&&!(stored&&stored.schedule))next.schedule.time=String(next.hour).padStart(2,'0')+':'+String(next.minute).padStart(2,'0');
    delete next.hour;delete next.minute;delete next.condition;return next;
  }
  function migrateLifeHubV75(){
    var before=clone(STATE),changed=false;
    if(!Array.isArray(STATE.savingsDeposits)){STATE.savingsDeposits=[];changed=true}
    if(!STATE.paydayCheckIns||typeof STATE.paydayCheckIns!=='object'||Array.isArray(STATE.paydayCheckIns)){STATE.paydayCheckIns={};changed=true}
    if(!STATE.study||typeof STATE.study!=='object'||Array.isArray(STATE.study)){STATE.study={};changed=true}
    if(!STATE.study.sessions||typeof STATE.study.sessions!=='object'||Array.isArray(STATE.study.sessions)){STATE.study.sessions={};changed=true}
    STATE.study.version=2;
    STATE.study.commitment=Object.assign({},STATE.study.commitment||{},{label:'AWS study',startDate:STUDY_START,endDate:STUDY_END,targetPerWeek:STUDY_TARGET,minimumMinutes:STUDY_MINUTES,dueDays:STUDY_DAYS.slice(),time:'14:00'});
    var existing=Array.isArray(STATE.reminders)?STATE.reminders:[];
    var byId={};existing.forEach(function(item){if(item&&item.id)byId[item.id]=item});
    var stable=REMINDER_DEFAULTS.map(function(item){return normalizeReminder(byId[item.id],item)});
    existing.forEach(function(item){if(!item||stable.some(function(known){return known.id===item.id}))return;var copy=clone(item);if(RETIRED_REMINDER_IDS.indexOf(copy.id)!==-1)copy.enabled=false;stable.push(copy)});
    if(JSON.stringify(existing)!==JSON.stringify(stable)){STATE.reminders=stable;changed=true}
    ['__bodyCompositionPlanV4','__rehabHabitV1','__injuryReentryV1','__challenge75V1','__runHabitRetiredV1','__tasksMigrated','__plannerMigrated'].forEach(function(flag){if(STATE[flag]!==true){STATE[flag]=true;changed=true}});
    if(STATE.__lifeHubV75!==true){STATE.__lifeHubV75=true;changed=true}
    var v76=migrateLifeHubV76();if(v76.changed)changed=true;
    return {changed:changed,before:before};
  }

  function currentStudySessions(){return STATE.study&&STATE.study.sessions&&typeof STATE.study.sessions==='object'?STATE.study.sessions:{}}
  function studyActive(key){key=dateKey(key);return key>=STUDY_START&&key<=STUDY_END}
  function studySessionsOn(key){return Object.keys(currentStudySessions()).map(function(id){return currentStudySessions()[id]}).filter(function(item){return item&&item.date===key})}
  function studyWeek(key){
    key=dateKey(key);var monday=mondayOf(key),sessions=[];
    for(var i=0;i<7;i++)studySessionsOn(addDays(monday,i)).forEach(function(item){if(Number(item.minutes)>=STUDY_MINUTES)sessions.push(item)});
    return {monday:monday,count:sessions.length,target:STUDY_TARGET,sessions:sessions};
  }
  function studyDue(value,hourOverride){
    var key=dateKey(value),hour=typeof hourOverride==='number'?hourOverride:new Date().getHours();
    return studyActive(key)&&STUDY_DAYS.indexOf(dateAtNoon(key).getDay())!==-1&&hour>=14&&studyWeek(key).count<STUDY_TARGET&&!studySessionsOn(key).some(function(item){return Number(item.minutes)>=STUDY_MINUTES});
  }
  function logStudyMinutesV75(minutes,note,hourOverride){
    var amount=Math.round(Number(minutes));if(!Number.isFinite(amount)||amount<1||amount>600)return false;
    var key=dateKey(new Date());if(!studyDue(key,hourOverride))return false;var snapshot=clone(STATE);if(!STATE.study)STATE.study={version:2,sessions:{}};if(!STATE.study.sessions)STATE.study.sessions={};
    var id=newId('study');STATE.study.sessions[id]={id:id,version:2,date:key,minutes:amount,note:String(note||'').trim().slice(0,240),loggedAt:new Date().toISOString()};
    if(!commit(snapshot,['study'],'study-log'))return false;renderDashboardV75();if(document.getElementById('page-insights')&&document.getElementById('page-insights').classList.contains('active'))renderInsightsV75();return true;
  }
  function submitStudyLog(){var input=document.getElementById('v75-study-minutes'),note=document.getElementById('v75-study-note'),amount=Number(input&&input.value);if(!Number.isInteger(amount)||amount<1||amount>600){error('v75-study-error','Enter actual minutes between 1 and 600.');return false}if(!logStudyMinutesV75(amount,note&&note.value)){error('v75-study-error','Study time could not be saved.');return false}return true}

  function paydayFor(year,monthIndex){var d=new Date(year,monthIndex,28),day=d.getDay();if(day===6)d.setDate(27);else if(day===0)d.setDate(26);return localDateKey(d)}
  function paydayForDate(value){var d=value instanceof Date?value:dateAtNoon(dateKey(value));return paydayFor(d.getFullYear(),d.getMonth())}
  function isPayday(value){var key=dateKey(value);return key===paydayForDate(key)}
  function markPaydayComplete(key){key=dateKey(key||new Date());if(!isPayday(key))return false;var snapshot=clone(STATE);if(!STATE.paydayCheckIns)STATE.paydayCheckIns={};STATE.paydayCheckIns[key]={date:key,completedAt:new Date().toISOString()};if(!commit(snapshot,['paydayCheckIns'],'payday-check-in'))return false;renderDashboardV75();renderFinanceV75();return true}

  function lastSunday(year,monthIndex){var d=new Date(year,monthIndex+1,0);d.setDate(d.getDate()-d.getDay());return localDateKey(d)}
  function monthlyResetDue(value,hourOverride){var key=dateKey(value),d=dateAtNoon(key),hour=typeof hourOverride==='number'?hourOverride:new Date().getHours();return key===lastSunday(d.getFullYear(),d.getMonth())&&hour>=11&&!((STATE.reviews&&STATE.reviews.monthly||{})[monthKey(key)]&&((STATE.reviews.monthly[monthKey(key)]||{}).version===2))}
  function sundayWeighInDue(value){var key=dateKey(value);return dateAtNoon(key).getDay()===0&&!(((STATE.metrics||{}).weight||[]).some(function(item){return item&&item.date===key}))}
  function activeWorkout(){var key=dateKey(new Date());return Object.keys(STATE.trainingSessions||{}).map(function(id){return STATE.trainingSessions[id]}).find(function(item){return item&&item.date===key&&item.status==='in-progress'})||null}

  function nowChoice(value,hourOverride){
    var key=dateKey(value||new Date()),active=activeWorkout();
    if(active)return {kind:'workout',resume:true,session:active};
    if(isPayday(key)&&!(STATE.paydayCheckIns||{})[key])return {kind:'payday'};
    if(monthlyResetDue(key,hourOverride))return {kind:'reset'};
    if(sundayWeighInDue(key))return {kind:'weight'};
    var occurrence=typeof effectiveWinterArcOccurrence==='function'?effectiveWinterArcOccurrence(key):null;
    if(occurrence&&occurrence.kind!=='rest')return {kind:'workout',resume:false,occurrence:occurrence};
    if(studyDue(key,hourOverride))return {kind:'study'};
    return null;
  }
  function nowCard(key){var choice=nowChoice(key),html='<section class="card v75-now" aria-labelledby="v75-now-title"><div class="v75-kicker">NOW</div>';
    if(!choice)return html+'<h2 id="v75-now-title">You are clear for now</h2><p>Come back when you want the next useful action.</p></section>';
    if(choice.kind==='workout')return html+'<h2 id="v75-now-title">'+(choice.resume?'Resume '+esc(choice.session.label):esc(choice.occurrence.label))+'</h2><p>'+(choice.resume?'Continue the workout already in progress.':'Your next rotation session is ready.')+'</p><button class="btn btn-accent" data-lifehub-click="openWinterArcWorkout(\''+key+'\''+(choice.resume?',\''+choice.session.id+'\'':',null')+',\'v75-now-workout-error\')">'+(choice.resume?'Resume workout':'Start workout')+'</button><p id="v75-now-workout-error" class="v75-error" role="alert" tabindex="-1" hidden></p></section>';
    if(choice.kind==='payday')return html+'<h2 id="v75-now-title">Payday check-in</h2><p>Record the debt payments and savings transfers you made this morning.</p><button class="btn btn-accent" data-lifehub-click="nav(\'finance\')">Open Finance</button></section>';
    if(choice.kind==='reset')return html+'<h2 id="v75-now-title">Monthly Reset</h2><p>Your prior four-week summary and four prompts are ready.</p><button class="btn btn-accent" data-lifehub-click="openMoreTab(\'reset\')">Start reset</button></section>';
    if(choice.kind==='weight')return html+'<h2 id="v75-now-title">Sunday weigh-in</h2><p>One entry will update your Movement trend.</p><button class="btn btn-accent" data-lifehub-click="document.getElementById(\'v75-weight-input\').focus()">Log weight</button></section>';
    return html+'<h2 id="v75-now-title">AWS study</h2><p>Log your actual minutes. Sessions of 30 minutes or more count toward 3 this week.</p><button class="btn btn-accent" data-lifehub-click="document.getElementById(\'v75-study-minutes\').focus()">Log study</button></section>';
  }

  function saveStepsV75(){var input=document.getElementById('v75-steps'),n=Number(input&&input.value);if(!Number.isInteger(n)||n<0||n>200000){error('v75-basics-error','Enter a whole-number step total between 0 and 200,000.');return false}var before=clone(STATE);if(typeof setDailySteps!=='function'||!setDailySteps(dateKey(new Date()),n)){STATE=before;error('v75-basics-error','Steps could not be saved. Your previous value is unchanged.');return false}renderDashboardV75();return true}
  function setWaterLitres(litres){var ml=Math.round(Number(litres)*1000),glassMl=Number(STATE.waterSettings&&STATE.waterSettings.glassMl||250);if(![500,1000,1500,2000].includes(ml)||!Number.isFinite(glassMl)||glassMl<=0)return false;var units=ml/glassMl,snapshot=clone(STATE),key=dateKey(new Date());if(!STATE.water)STATE.water={};STATE.water[key]=units;if(!commit(snapshot,['water'],'water-total')){error('v75-basics-error','Water could not be saved. Your previous total is unchanged.');return false}renderDashboardV75();return true}
  function clearWaterV75(){var snapshot=clone(STATE),key=dateKey(new Date());if(!STATE.water)STATE.water={};delete STATE.water[key];if(!commit(snapshot,['water'],'water-clear')){error('v75-basics-error','Water could not be cleared.');return false}renderDashboardV75();return true}
  function saveWeightV75(){var input=document.getElementById('v75-weight-input'),value=Math.round(Number(input&&input.value)*10)/10;if(!Number.isFinite(value)||value<30||value>300){error('v75-weight-error','Enter a weight between 30 and 300 in your usual unit.');return false}var snapshot=clone(STATE),key=dateKey(new Date());if(!STATE.metrics)STATE.metrics={};if(!Array.isArray(STATE.metrics.weight))STATE.metrics.weight=[];STATE.metrics.weight.push({id:newId('weight'),date:key,value:value,note:''});if(!commit(snapshot,['metrics'],'weight-create')){error('v75-weight-error','Weight could not be saved.');return false}renderDashboardV75();return true}

  function basicsCard(key){var model=typeof dailyBasicsStatus==='function'?dailyBasicsStatus(key):null,rows=model&&model.rows||[],steps=rows.find(function(r){return r.id==='steps'})||{},water=rows.find(function(r){return r.id==='water'})||{},workout=rows.find(function(r){return r.id==='workout'})||{};return '<section class="card v75-basics" aria-labelledby="v75-basics-title"><div class="v75-card-head"><div><div class="v75-kicker">TODAY</div><h2 id="v75-basics-title">Daily Basics</h2></div></div><div class="v75-basic-row"><div><strong>Steps</strong><span>Exact total · complete at 8,000</span></div><div class="v75-inline"><input id="v75-steps" aria-label="Today’s exact step total" type="number" min="0" max="200000" step="1" inputmode="numeric" value="'+(steps.value||'')+'"><button class="btn btn-sm" data-lifehub-click="saveStepsV75()">Save</button><span class="v75-state">'+(steps.done?'Done':'')+'</span></div></div><div class="v75-basic-row"><div><strong>Water</strong><span>Set today’s total in 500 ml chunks</span></div><div class="v75-choice-row" role="group" aria-label="Today’s water total">'+[0.5,1,1.5,2].map(function(n){var label=n===2?'2L+':n+'L';return '<button class="v75-choice '+(Number(water.value)===n*1000?'selected':'')+'" aria-pressed="'+(Number(water.value)===n*1000)+'" data-lifehub-click="setWaterLitres('+n+')">'+label+'</button>'}).join('')+'<button class="v75-choice" data-lifehub-click="clearWaterV75()">Clear</button></div></div><div class="v75-basic-row"><div><strong>Planned workout</strong><span>'+esc(workout.status||'Finish the prescribed session to complete this')+'</span></div><span class="v75-state">'+(workout.done?'Done':'')+'</span></div><p id="v75-basics-error" class="v75-error" role="alert" tabindex="-1" hidden></p></section>'}
  function workoutSurface(key){var active=activeWorkout(),occ=typeof effectiveWinterArcOccurrence==='function'?effectiveWinterArcOccurrence(key):null;if(!active&&(!occ||occ.kind==='rest'))return '';return '<section class="card v75-action-card"><div><div class="v75-kicker">WORKOUT</div><h2>'+(active?'Continue '+esc(active.label):esc(occ.label))+'</h2><p>'+(active?'Your exact active session is waiting.':'Next in your flexible R2 rotation.')+'</p><p id="v75-dashboard-workout-error" class="v75-error" role="alert" tabindex="-1" hidden></p></div><button class="btn btn-accent" data-lifehub-click="openWinterArcWorkout(\''+key+'\''+(active?',\''+active.id+'\'':',null')+',\'v75-dashboard-workout-error\')">'+(active?'Resume Workout':'Start Workout')+'</button></section>'}
  function studyCard(key){if(!studyDue(key))return '';var week=studyWeek(key);return '<section class="card"><div class="v75-card-head"><div><div class="v75-kicker">TEMPORARY COMMITMENT</div><h2>AWS study</h2><p>'+week.count+' of '+STUDY_TARGET+' qualifying sessions this week · ends 31 Dec 2026</p></div></div><div class="v75-inline"><label for="v75-study-minutes">Actual minutes</label><input id="v75-study-minutes" type="number" min="1" max="600" step="1" inputmode="numeric" placeholder="30"><input id="v75-study-note" maxlength="240" aria-label="Study note" placeholder="Optional note"><button class="btn" data-lifehub-click="submitStudyLog()">Log</button></div><p id="v75-study-error" class="v75-error" role="alert" tabindex="-1" hidden></p></section>'}
  function weightCard(key){if(!sundayWeighInDue(key))return '';return '<section class="card"><div class="v75-kicker">SUNDAY</div><h2>Weekly weigh-in</h2><div class="v75-inline"><label for="v75-weight-input">Weight (kg)</label><input id="v75-weight-input" type="number" min="30" max="300" step="0.1" inputmode="decimal"><button class="btn" data-lifehub-click="saveWeightV75()">Save</button></div><p id="v75-weight-error" class="v75-error" role="alert" tabindex="-1" hidden></p></section>'}
  function resetDueCard(key){return monthlyResetDue(key)?'<section class="card v75-quiet"><h2>Monthly Reset</h2><p>Your four-week summary is ready.</p><button class="btn btn-ghost" data-lifehub-click="openMoreTab(\'reset\')">Open reset</button></section>':''}
  function paydayCard(key){return isPayday(key)&&!(STATE.paydayCheckIns||{})[key]?'<section class="card v75-quiet"><h2>Payday check-in</h2><p>Record today’s debt payments and savings transfers.</p><button class="btn btn-ghost" data-lifehub-click="nav(\'finance\')">Open Finance</button></section>':''}
  function renderDashboardV75(){var el=document.getElementById('v75-dashboard');if(!el)return;var key=dateKey(new Date()),d=dateAtNoon(key);el.innerHTML='<header class="v75-page-header"><div><span class="v75-kicker">'+esc(d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase())+'</span><h1>What should I do next?</h1><p>One action, then today’s basics.</p></div></header>'+nowCard(key)+basicsCard(key)+workoutSurface(key)+paydayCard(key)+resetDueCard(key)+weightCard(key)+studyCard(key)+'<a class="v75-insights-link" href="#insights" data-lifehub-click="event.preventDefault();nav(\'insights\')">View four-week insights →</a>'}

  function completedRotationSessions(){return Object.keys(STATE.trainingSessions||{}).map(function(id){return STATE.trainingSessions[id]}).filter(function(s){return s&&s.status==='completed'&&s.qualifies===true&&s.planContentRevision==='R2'}).sort(function(a,b){return String(b.completedAt||b.date).localeCompare(String(a.completedAt||a.date))})}
  function weightTrend(){var rows=((STATE.metrics||{}).weight||[]).slice().filter(function(item){return item&&item.date&&Number.isFinite(Number(item.value))}).sort(function(a,b){return a.date.localeCompare(b.date)}),recent=rows.slice(-12);if(!recent.length)return '<p class="v75-empty">Sunday weigh-ins will build a simple trend here.</p>';var min=Math.min.apply(null,recent.map(function(x){return Number(x.value)})),max=Math.max.apply(null,recent.map(function(x){return Number(x.value)})),span=Math.max(1,max-min),points=recent.map(function(x,i){return (recent.length===1?50:i/(recent.length-1)*100)+','+(42-(Number(x.value)-min)/span*34)}).join(' ');return '<svg class="v75-spark" viewBox="0 0 100 48" role="img" aria-label="Weight trend"><polyline points="'+points+'" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="v75-trend-labels"><span>'+esc(recent[0].date)+' · '+recent[0].value+'</span><span>'+esc(recent[recent.length-1].date)+' · '+recent[recent.length-1].value+'</span></div>'}
  function liftingWeek(value){var key=dateKey(value),monday=mondayOf(key),sunday=addDays(monday,6),sessions=completedRotationSessions().filter(function(s){return s.kind==='strength'&&s.date>=monday&&s.date<=sunday});return {count:sessions.length,target:4,sessions:sessions}}
